// src/apolloClient.js
import { ApolloClient, InMemoryCache, HttpLink } from '@apollo/client';
import { GraphQLWsLink } from '@apollo/client/link/subscriptions';
import { createClient } from 'graphql-ws';
import { split } from '@apollo/client';
import { getMainDefinition } from '@apollo/client/utilities';

// HTTP-ссылка для запросов и мутаций
const httpLink = new HttpLink({
    uri: 'http://localhost:8080/query', // Важно указать полный путь
});

// WebSocket-ссылка для подписок
const wsLink = new GraphQLWsLink(createClient({
    url: 'ws://localhost:8080/query', // WebSocket endpoint
}));

// Разделение ссылок в зависимости от типа операции
const splitLink = split(
    ({ query }) => {
        const definition = getMainDefinition(query);
        return (
            definition.kind === 'OperationDefinition' &&
            definition.operation === 'subscription'
        );
    },
    wsLink,
    httpLink,
);

const client = new ApolloClient({
    link: splitLink,
    cache: new InMemoryCache(),
});

export default client;
